	"Account":"select iaccountid, icustomerid, vcexternalaccountid, iaccounttypeid, vcifsc, vcaccountproviderid, vcaccountname, dtonboardingdate, dtexpirydate, imcc, bmerchant, bverified, irecordstatus, dtentrydatetime from masters.accounts order by dtentrydatetime desc limit 50000",
	"VPA": "select ivpaid, iaccountid, vcexternaladdressid, vcaddress, iproductid, vcvpaname, bverified, imcc, dtonboardingdate, dtexpirydate, bmerchant, ivpaproviderid, bprofiled, dtfirsttransaction, dtlasttransaction, irecordstatus, dtentrydatetime from masters.vpa order by dtentrydatetime desc limit 50000",
	"Customer": "SELECT icustomerid, vcexternalcustid, vccustomername, vccustomertype, vcsalutation, vcverifiedname, vcgender, dtdoidob, dtonboardingdate, vcpostalcode, vcemail, vcregisteredmobile, imcc, vcidentitytype1, vcidentitydetails1, vcidentitytype2, vcidentitydetails2, vcregisteredaddressgeolocation, iadm3, iadm2, iadm1, vccountrycode, vcattribs->>''kyc_type'' as \"kyc type\", vcattribs->>''phone_number'' as \"phone number\", vcattribs->>''employment_type'' as \"employment type\", vcattribs->>''onboarding_state'' as \"onboarding state\", vcattribs->>''declared_salary_max'' as \"declared salary_max\", vcattribs->>''declared_salary_min'' as \"declared salary_min\", vcattribs->>''liveness_geolocation'' as \"liveness geolocation\",  vcattribs->>''internal_liveness_score'' as \"internal livness_score\", vcattribs->>''shipping_address_state'' as \"shipping address_state\",  vcattribs->>''mailing_address_postalcode'' as \"mailing address_postalcode\", vcattribs->>''shipping_address_postalcode'' as \"shipping address_postalcode\", irecordstatus, dtentrydatetime FROM masters.customers :AttribsForm order by dtentrydatetime desc limit 50000;"
}'::TEXT, formattingrequiered=false WHERE idashboardqueryid=48;

